import os
from google.generativeai.client import get_default_retriever_async_client
import google.generativeai as genai

class GeminiClient:
    def __init__(self):
        api_key = os.environ.get("GOOGLE_API_KEY")
        if not api_key:
            raise ValueError("GOOGLE_API_KEY environment variable not set.")
        genai.configure(api_key=api_key)

    def get_generative_model(self, model_name: str = "gemini-2.5-flash"):
        return genai.GenerativeModel(model_name)

    def get_embedding_model(self, model_name: str = "embedding-001"):
        return genai.EmbeddingModel(model_name)

import json
from model_client import GeminiClient
from model_models import ModelPayload, ModelResponse

def extract_json(payload: ModelPayload) -> ModelResponse:
    client = GeminiClient()
    model = client.get_generative_model(model_name="gemini-pro") # gemini-pro is good for structured output

    prompt = f"Extract JSON from the following text. The JSON should represent key-value pairs of important information.\n\nText: {payload.text}\n\nJSON:"

    response = model.generate_content(prompt)

    try:
        extracted_content = json.loads(response.text)
    except json.JSONDecodeError:
        extracted_content = {"error": "Could not parse JSON", "raw_output": response.text}

    return ModelResponse(text=response.text, extracted_content=extracted_content)

from typing import Dict, Any
from model_client import GeminiClient
from model_models import ModelPayload

def check_safety(payload: ModelPayload) -> Dict[str, Any]:
    client = GeminiClient()
    model = client.get_generative_model(model_name="gemini-pro")

    # Make a dummy call to get a response object with safety attributes
    # In a real scenario, you might integrate this check within a generation call
    response = model.generate_content(payload.text)

    safety_feedback = {
        "prompt_blocked": False,
        "safety_ratings": []
    }

    if response.prompt_feedback and response.prompt_feedback.block_reason:
        safety_feedback["prompt_blocked"] = True
        safety_feedback["block_reason"] = response.prompt_feedback.block_reason.name

    if response.candidates:
        # Check safety ratings for the generated content
        candidate = response.candidates[0]
        if candidate.finish_reason and candidate.finish_reason.name == "SAFETY":
            safety_feedback["generated_blocked"] = True
            safety_feedback["generated_block_reason"] = candidate.finish_reason.name

        if candidate.safety_ratings:
            for rating in candidate.safety_ratings:
                safety_feedback["safety_ratings"].append({
                    "category": rating.category.name,
                    "probability": rating.probability.name,
                    "blocked": rating.blocked
                })

    return safety_feedback

from model_client import GeminiClient
from model_models import ModelPayload, ModelResponse

def get_output_embedding(payload: ModelPayload) -> ModelResponse:
    client = GeminiClient()
    model = client.get_embedding_model(model_name="embedding-001")

    # The embedding model expects a list of texts
    result = model.embed_content(contents=[payload.text])

    embeddings = []
    if result.embeddings:
        for embedding_obj in result.embeddings:
            embeddings.extend(embedding_obj.values)

    return ModelResponse(text=payload.text, embeddings=embeddings)
